    for (int i = tid; i < 64 * 128; i += blockDim.x) {
        int r = i / 128, c = i % 128;
        sK[i] = __float2bfloat16((float)(r * 128 + c) * 0.001f - 8.f);
    }
    __syncthreads();
    if (tid >= 32) return;

    // Q fragments from formula: Q[r][c] = (r*128+c)*0.002f - 4.f
    uint32_t qA[8][4];
    for (int kk = 0; kk < 8; ++kk) {
        const int c0 = kk * 16 + 2 * t;
        auto mk = [&](int row, int cc) {
