        };
        uint32_t lo = (uint32_t)mk(g, c0) | ((uint32_t)mk(g, c0 + 1) << 16);
        uint32_t hi = (uint32_t)mk(g, c0 + 8) | ((uint32_t)mk(g, c0 + 9) << 16);
        uint32_t lo8 = (uint32_t)mk(g + 8, c0) | ((uint32_t)mk(g + 8, c0 + 1) << 16);
        uint32_t hi8 = (uint32_t)mk(g + 8, c0 + 8) | ((uint32_t)mk(g + 8, c0 + 9) << 16);
        qA[kk][0] = lo; qA[kk][1] = hi; qA[kk][2] = lo8; qA[kk][3] = hi8;
    }

    float accS[8][4];
    for (int nn = 0; nn < 8; ++nn)
        for (int j = 0; j < 4; ++j) accS[nn][j] = 0.f;

    for (int kk = 0; kk < 8; ++kk) {
        const int hd0 = kk * 16;
        for (int ch = 0; ch < 4; ++ch) {
            const int kv0 = ch * 16;
            // non-trans x4 on region [kv0..kv0+15][hd0..hd0+15]:
            // q0=(kv0+0,hd0+0) q1=(kv0+0,hd0+8) q2=(kv0+8,hd0+0) q3=(kv0+8,hd0+8)
            uint32_t q[4] = {
                smem_u32(&sK[(kv0 + 0) * 128 + hd0 + 0]),
