            // lane supplies base + (lane%8)*256 bytes (row stride)
            uint32_t addr = q[lane / 8] + (lane % 8) * 256;
            uint32_t frag[4];
            ldmatrix_x4(frag, addr);
            // n-step 2ch: B={frag0,frag1} (kv cols kv0..kv0+7)
